from __future__ import annotations

import base64
from pathlib import Path

finalizer = Path(__file__).with_name("cognia_only_rag_finalize.py")
source = finalizer.read_text(encoding="utf-8")
marker = "# Final source scan: no runtime/provider switch or local Knowledge RAG tokens may remain.\n"
if marker not in source:
    raise RuntimeError("finalizer guard marker not found")

payload = base64.b64decode("").decode("utf-8")
source = source.replace(marker, payload + "\n" + marker, 1)
exec(compile(source, str(finalizer), "exec"), {"__file__": str(finalizer), "__name__": "__main__"})
Path(__file__).unlink()
